{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Three types of procurement methods are described in 2 CFR § 200.320: informal procurement methods (for micro-purchases and simplified acquisitions), formal procurement methods (through sealed bids or proposals), and noncompetitive procurement methods.",
        "kind": "statement",
        "modality": "not_stated",
        "references": [
          "§ 200.320"
        ]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For any of the three procurement methods described in 2 CFR § 200.320, the recipient or subrecipient must maintain and use documented procurement procedures, consistent with the standards of this section and §§ 200.317, 200.318, and 200.319.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "§ 200.317",
          "§ 200.318",
          "§ 200.319",
          "§ 200.320"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Informal procurement methods expedite the completion of transactions, minimize administrative burdens, and reduce costs.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Informal procurement methods may be used when the value of the procurement transaction under the Federal award does not exceed the simplified acquisition threshold as defined in § 200.1.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "§ 200.1"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Recipients and subrecipients may establish a lower threshold for informal procurement methods.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For micro-purchases, the aggregate amount of the procurement transaction does not exceed the micro-purchase threshold defined in § 200.1.",
        "kind": "statement",
        "modality": "not_stated",
        "references": [
          "§ 200.1"
        ]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "To the extent practicable, the recipient or subrecipient should distribute micro-purchases equitably among qualified suppliers.",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "logic_explanation": "Micro-purchases may be awarded without competitive quotes only if both conditions are satisfied: the price is considered reasonable based on the enumerated factors, and supporting documentation is maintained.",
        "statement": "Micro-purchases may be awarded without soliciting competitive price or rate quotations if the recipient or subrecipient considers the price reasonable based on research, experience, purchase history, or other information, and maintains documents to support its conclusion.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Purchase cards may be used as a method of payment for micro-purchases.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The recipient or subrecipient is responsible for determining and documenting an appropriate micro-purchase threshold based on internal controls, an evaluation of risk, and its documented procurement procedures.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The micro-purchase threshold used by the recipient or subrecipient must be authorized or not prohibited under State, local, or tribal laws or regulations.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The recipient or subrecipient may establish a micro-purchase threshold higher than the Federal threshold established in the Federal Acquisition Regulations (FAR) in accordance with paragraphs (a)(1)(iv) and (v) of § 200.320.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "§ 200.320(a)(1)(iv)",
          "§ 200.320(a)(1)(v)"
        ]
      }
    },
    {
      "unit": "F006:F009",
      "unit_attributes": {
        "logic_explanation": "Self-certification allows raising the micro-purchase threshold up to $50,000 annually provided documentation is maintained, and requires a justification, threshold identification, plus at least one of the three listed supporting documentation items.",
        "statement": "The recipient or subrecipient may self-certify a micro-purchase threshold higher than the micro-purchase threshold identified in the FAR up to $50,000 on an annual basis, and must maintain documentation to be made available to the Federal agency or pass-through entity and auditors in accordance with § 200.334; the self-certification must include a justification, clear identification of the threshold, and supporting documentation of any of the following: (A) a qualification as a low-risk auditee in accordance with the criteria in § 200.520 for the most recent audit; (B) an annual internal institutional risk assessment to identify, mitigate, and manage financial risks; or (C) for public institutions, that a higher threshold is consistent with State law.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "§ 200.334",
          "§ 200.520"
        ]
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "logic_explanation": "Approval by the cognizant agency for indirect costs is required to establish micro-purchase thresholds exceeding $50,000, conditioned on submitting a request satisfying paragraph (a)(1)(iv).",
        "statement": "Micro-purchase thresholds higher than $50,000 must be approved by the cognizant agency for indirect costs, and the recipient or subrecipient must submit a request that includes the requirements in paragraph (a)(1)(iv) of § 200.320.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "§ 200.320(a)(1)(iv)"
        ]
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "An increased micro-purchase threshold over $50,000 is valid until any factor that was relied on in the establishment and rationale of the threshold changes.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For simplified acquisitions, the aggregate dollar amount of the procurement transaction is higher than the micro-purchase threshold but does not exceed the simplified acquisition threshold.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If simplified acquisition procedures are used, price or rate quotations must be obtained from an adequate number of qualified sources.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Unless specified by the Federal agency, the recipient or subrecipient may exercise judgment in determining what number of qualified sources is adequate when obtaining price or rate quotations under simplified acquisition procedures.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The recipient or subrecipient is responsible for determining an appropriate simplified acquisition threshold based on internal controls, an evaluation of risk, and its documented procurement procedures, which may be lower than, but must not exceed, the threshold established in the FAR.",
        "kind": "prohibition",
        "modality": "must_not"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Formal procurement methods are required when the value of the procurement transaction under a Federal award exceeds the simplified acquisition threshold of the recipient or subrecipient; they are competitive, require public notice, and include sealed bids or proposals.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "§ 200.320(a)(2)(ii)"
        ]
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Sealed bids is a procurement method in which bids are publicly solicited through an invitation and a firm fixed-price contract (lump sum or unit price) is awarded to the responsible bidder whose bid conforms with all the material terms and conditions of the invitation and is the lowest in price.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The sealed bids procurement method is preferred for procuring construction services.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F015:F017",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For sealed bidding to be feasible, the following conditions should be present: (A) a complete, adequate, and realistic specification or purchase description is available; (B) two or more responsible bidders have been identified as willing and able to compete effectively for the business; and (C) the procurement lends itself to a firm-fixed-price contract, and the selection of the successful bidder can be made principally based on price.",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F019",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If sealed bids are used, bids must be solicited from an adequate number of qualified sources, providing them with sufficient response time prior to the date set for opening the bids.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F019",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "When using sealed bids, unless specified by the Federal agency, the recipient or subrecipient may exercise judgment in determining what number of qualified sources is adequate.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F019",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For local governments using sealed bids, the invitation for bids must be publicly advertised.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F020",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If sealed bids are used, the invitation for bids must define the items or services with specific information, including any required specifications, for the bidder to properly respond.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F021",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If sealed bids are used, all bids will be opened at the time and place prescribed in the invitation for bids, and for local governments, the bids must be opened publicly.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If sealed bids are used, a firm-fixed-price contract is awarded in writing to the lowest responsive bid and responsible bidder, and when specified in the invitation for bids, factors such as discounts, transportation cost, and life-cycle costs must be considered in determining which bid is the lowest.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Under sealed bids, payment discounts must only be used to determine the low bid when the recipient or subrecipient determines they are a valid factor based on prior experience.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F023",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "If sealed bids are used, the recipient or subrecipient must document and provide a justification for all bids it rejects.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "Proposals is a procurement method used when conditions are not appropriate for using sealed bids, and this procurement method may result in either a fixed-price or cost-reimbursement contract.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F025",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "When using proposals, requests for proposals require public notice, all evaluation factors and their relative importance must be identified, proposals must be solicited from multiple qualified entities, and to the maximum extent practicable, any proposals submitted in response to the public notice must be considered.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F026",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "When using proposals, the recipient or subrecipient must have written procedures for conducting technical evaluations and making selections.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F027",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "When using proposals, contracts must be awarded to the responsible offeror whose proposal is most advantageous to the recipient or subrecipient considering price and other factors.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F028",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The recipient or subrecipient may use competitive proposal procedures for qualifications-based procurement of architectural/engineering (A/E) professional services whereby the offeror's qualifications are evaluated, and the most qualified offeror is selected, subject to negotiation of fair and reasonable compensation.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F028",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "The qualifications-based competitive proposal method where price is not used as a selection factor can only be used to procure architectural/engineering (A/E) professional services, and may not be used to purchase other services provided by A/E firms that are a potential source to perform the proposed effort.",
        "kind": "prohibition",
        "modality": "must_not"
      }
    },
    {
      "unit": "F029:F034",
      "unit_attributes": {
        "logic_explanation": "Noncompetitive procurement is prohibited unless at least one of the five specific circumstances (1 through 5) applies.",
        "statement": "A noncompetitive procurement method may only be used if one of the following circumstances applies: (1) the aggregate amount of the procurement transaction does not exceed the micro-purchase threshold; (2) the procurement transaction can only be fulfilled by a single source; (3) the public exigency or emergency for the requirement will not permit a delay resulting from providing public notice of a competitive solicitation; (4) the recipient or subrecipient requests in writing to use a noncompetitive procurement method, and the Federal agency or pass-through entity provides written approval; or (5) after soliciting several sources, competition is determined inadequate.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "§ 200.320(a)(1)"
        ]
      }
    }
  ]
}
